import React, { useState, useEffect } from 'react';
import './PostForm.css';

const PostForm = ({ onSubmit, onUpdate, editingPost, onCancelEdit, loading }) => {
  const [formData, setFormData] = useState({
    title: '',
    content: '',
    author: '',
    publishedDate: new Date().toISOString().split('T')[0]
  });
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (editingPost) {
      setFormData({
        title: editingPost.title,
        content: editingPost.content,
        author: editingPost.author,
        publishedDate: new Date(editingPost.publishedDate).toISOString().split('T')[0]
      });
      setErrors({});
    } else {
      setFormData({
        title: '',
        content: '',
        author: '',
        publishedDate: new Date().toISOString().split('T')[0]
      });
      setErrors({});
    }
  }, [editingPost]);

  const validateForm = () => {
    const newErrors = {};
    if (!formData.title.trim()) newErrors.title = 'Title is required';
    if (!formData.content.trim()) newErrors.content = 'Content is required';
    if (!formData.author.trim()) newErrors.author = 'Author is required';
    if (!formData.publishedDate) newErrors.publishedDate = 'Published date is required';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validateForm()) return;

    setSubmitting(true);
    try {
      if (editingPost) {
        await onUpdate(editingPost._id, formData);
      } else {
        await onSubmit(formData);
      }
      setFormData(prev => ({ ...prev, title: '', content: '', author: '' }));
    } catch (err) {
      setErrors({ submit: err.message });
    } finally {
      setSubmitting(false);
    }
  };

  const isEditing = Boolean(editingPost);

  return (
    <div className="card glass-card border-0 shadow-sm overflow-hidden" aria-labelledby="form-title">
      <div className="card-header bg-transparent border-bottom border-light-subtle d-flex align-items-center justify-content-between p-3 p-md-4">
        <div className="d-flex align-items-center gap-2">
          <i className={`bi ${isEditing ? 'bi-pencil-square text-warning' : 'bi-plus-circle text-primary'} fs-5`}></i>
          <h2 id="form-title" className="h5 fw-bold mb-0 text-dark">
            {isEditing ? 'Edit Post' : 'Create New Post'}
          </h2>
        </div>
        {isEditing && (
          <button
            type="button"
            className="btn btn-sm btn-outline-secondary rounded-pill d-inline-flex align-items-center gap-1"
            onClick={onCancelEdit}
          >
            <i className="bi bi-x-lg"></i>
            Cancel
          </button>
        )}
      </div>

      <div className="card-body p-3 p-md-4">
        <form onSubmit={handleSubmit} noValidate>
          {/* Title */}
          <div className="mb-3">
            <label htmlFor="title" className="form-label fw-semibold small text-secondary">
              Title <span className="text-danger">*</span>
            </label>
            <input
              type="text"
              id="title"
              name="title"
              value={formData.title}
              onChange={handleChange}
              className={`form-control bg-white bg-opacity-75 ${errors.title ? 'is-invalid' : ''}`}
              placeholder="e.g. Exploring Modern Web Development"
              maxLength={200}
              disabled={submitting || loading}
              aria-invalid={errors.title ? 'true' : 'false'}
            />
            {errors.title && (
              <div className="invalid-feedback">{errors.title}</div>
            )}
          </div>

          {/* Author & Published Date in row */}
          <div className="row g-3 mb-3">
            <div className="col-sm-6">
              <label htmlFor="author" className="form-label fw-semibold small text-secondary">
                Author <span className="text-danger">*</span>
              </label>
              <input
                type="text"
                id="author"
                name="author"
                value={formData.author}
                onChange={handleChange}
                className={`form-control bg-white bg-opacity-75 ${errors.author ? 'is-invalid' : ''}`}
                placeholder="Your name"
                maxLength={100}
                disabled={submitting || loading}
                aria-invalid={errors.author ? 'true' : 'false'}
              />
              {errors.author && (
                <div className="invalid-feedback">{errors.author}</div>
              )}
            </div>

            <div className="col-sm-6">
              <label htmlFor="publishedDate" className="form-label fw-semibold small text-secondary">
                Published Date <span className="text-danger">*</span>
              </label>
              <input
                type="date"
                id="publishedDate"
                name="publishedDate"
                value={formData.publishedDate}
                onChange={handleChange}
                className={`form-control bg-white bg-opacity-75 ${errors.publishedDate ? 'is-invalid' : ''}`}
                disabled={submitting || loading}
                aria-invalid={errors.publishedDate ? 'true' : 'false'}
              />
              {errors.publishedDate && (
                <div className="invalid-feedback">{errors.publishedDate}</div>
              )}
            </div>
          </div>

          {/* Content */}
          <div className="mb-3">
            <label htmlFor="content" className="form-label fw-semibold small text-secondary">
              Content <span className="text-danger">*</span>
            </label>
            <textarea
              id="content"
              name="content"
              value={formData.content}
              onChange={handleChange}
              className={`form-control bg-white bg-opacity-75 ${errors.content ? 'is-invalid' : ''}`}
              placeholder="Write your blog post content here..."
              rows={6}
              disabled={submitting || loading}
              aria-invalid={errors.content ? 'true' : 'false'}
            />
            {errors.content && (
              <div className="invalid-feedback">{errors.content}</div>
            )}
          </div>

          {errors.submit && (
            <div className="alert alert-danger py-2 px-3 small d-flex align-items-center gap-2 mb-3" role="alert">
              <i className="bi bi-exclamation-circle-fill"></i>
              <span>{errors.submit}</span>
            </div>
          )}

          {/* Actions */}
          <div className="d-flex gap-2 pt-2">
            <button
              type="submit"
              className="btn btn-primary rounded-pill px-4 py-2 flex-grow-1 flex-sm-grow-0 d-inline-flex align-items-center justify-content-center gap-2 shadow-sm"
              disabled={submitting || loading}
            >
              {submitting ? (
                <>
                  <span className="spinner-border spinner-border-sm" aria-hidden="true"></span>
                  <span>Saving...</span>
                </>
              ) : (
                <>
                  <i className={`bi ${isEditing ? 'bi-check2-circle' : 'bi-send-fill'}`}></i>
                  <span>{isEditing ? 'Update Post' : 'Publish Post'}</span>
                </>
              )}
            </button>

            {isEditing && (
              <button
                type="button"
                className="btn btn-outline-secondary rounded-pill px-3"
                onClick={onCancelEdit}
                disabled={submitting || loading}
              >
                Cancel
              </button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

export default PostForm;
